-- GENERATED by scripts/fingerprint_deadlines.py --only (data/ now); all 13 fields. Read-only.
-- Returns only problem rows (missing = expected but not live, extra = live but not expected, mismatch = different
-- content), then one 'total' row with the counts. Every row but 'total' is a problem.
with expected (id, md5) as (values
 ('c4d441a5-319c-52a6-8186-d61c3dd46611'::uuid, 'dc01b9fa9b29970bff9c668c433ff8c1'),
 ('1a3d8818-4951-577c-a5f5-05f8bc194cff'::uuid, 'bdeb978f8de7531f93cf84ae28ab5f2b'),
 ('f12c1219-cf27-5ec3-87c6-799c17202604'::uuid, '3064521a66b37b3cb81d87e5882817fc'),
 ('b6676abb-3065-50bc-9e31-a99ddde42fd2'::uuid, '7296ae30dcd9a3c0797eb033a2d3307d'),
 ('53eed6f5-91e8-572d-9f3b-fed7183014df'::uuid, '0f04bcfa8030fc267d0982358e86ea25'),
 ('64d7b951-c42a-5da6-9e53-27723cbcf1e6'::uuid, '52e12202b468fe9756a5d748ebd6e5e9'),
 ('d67b4c44-6aaa-51b8-aa7b-940de9aecefe'::uuid, '7f14634169889207c44474b3810411a6'),
 ('ed6f9332-ebf1-5a87-be52-f0fec1ee3d3f'::uuid, 'ab178eb132714b32dda7b86eea520a91'),
 ('fc2a20c8-52bb-5695-a0b9-776482af6700'::uuid, '7c19bf109480f4fbb3cad919c02aa749'),
 ('0fc686cb-d865-5014-8f2c-1cf5c2784807'::uuid, '43790e96116b434e05e419383c9cd85a')),
live as (
  select d.id, md5(concat_ws('|', d.id::text, d.kind, coalesce(d.plan_key,''), coalesce(d.label,''), coalesce(d.due_date::text,''), coalesce(d.notes,''), coalesce(d.intake,''), coalesce(d.program_id::text,''), coalesce(d.source_id::text,''), coalesce(d.notification_date::text,''), coalesce(d.notification_note,''), coalesce(d.cycle,''), coalesce(d.institution_id::text,''))) as md5
  from public.deadlines d
  join public.institutions i on i.id = d.institution_id
  where i.slug in ('melbourne', 'ucl')
),
problems as (
  select coalesce(e.id, l.id) as id,
         case when l.id is null then 'missing' when e.id is null then 'extra' else 'mismatch' end as problem
  from expected e full join live l on l.id = e.id
  where l.id is null or e.id is null or l.md5 <> e.md5
)
select id, problem from (
  select id::text as id, problem, 0 as ord from problems
  union all
  select 'total', format('%s live rows, %s expected, %s problems',
                         (select count(*) from live), (select count(*) from expected), (select count(*) from problems)), 1
) r
order by ord, id;
